WITH RankedPosts AS (SELECT p.Id, p.Title, p.CreationDate, p.Score, p.ViewCount, p.AnswerCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS rn, COUNT(v.Id) FILTER(WHERE v.VoteTypeId = 2) OVER (PARTITION BY p.OwnerUserId) AS UpVotes, COUNT(v.Id) FILTER(WHERE v.VoteTypeId = 3) OVER (PARTITION BY p.OwnerUserId) AS DownVotes FROM Posts AS p LEFT JOIN Votes AS v ON p.Id = v.PostId WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), RecentBadges AS (SELECT b.UserId, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b WHERE b.Date >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR GROUP BY b.UserId), PostHistoryStats AS (SELECT ph.PostId, COUNT(*) AS EditCount, MAX(ph.CreationDate) AS LastEditDate FROM PostHistory AS ph WHERE ph.PostHistoryTypeId IN (4, 5, 6) GROUP BY ph.PostId) SELECT p.Title, p.CreationDate, p.Score, p.ViewCount, rp.UpVotes, rp.DownVotes, COALESCE(rb.BadgeNames, 'No Badges') AS UserBadges, COALESCE(phs.EditCount, 0) AS EditCount, phs.LastEditDate FROM RankedPosts AS rp JOIN Posts AS p ON rp.Id = p.Id LEFT JOIN Users AS u ON p.OwnerUserId = u.Id LEFT JOIN RecentBadges AS rb ON u.Id = rb.UserId LEFT JOIN PostHistoryStats AS phs ON p.Id = phs.PostId WHERE rp.rn = 1 ORDER BY p.Score DESC NULLS FIRST, p.ViewCount DESC NULLS FIRST LIMIT 100